-- TOC entry 267 (class 1255 OID 16843)
-- Name: accept_admin_request(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.accept_admin_request(p_request_id bigint, p_decided_by_admin_id bigint, p_note text DEFAULT NULL::text) RETURNS TABLE(request_id bigint, personnel_id bigint, status character varying, role_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_personnel_id bigint;
  v_status varchar(20);
  v_admin_role_id integer;
BEGIN
  SELECT ar.personnel_id, ar.status
  INTO v_personnel_id, v_status
  FROM public.admin_requests ar
  WHERE ar.id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Admin request % not found', p_request_id;
  END IF;

  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'Admin request % is already %', p_request_id, v_status;
  END IF;

  SELECT r.id
  INTO v_admin_role_id
  FROM public.roles r
  WHERE lower(r.name) = 'admin'
  LIMIT 1;

  IF v_admin_role_id IS NULL THEN
    RAISE EXCEPTION 'Role "admin" not found in roles table';
  END IF;

  UPDATE public.admins
  SET role_id = v_admin_role_id
  WHERE id = v_personnel_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Personnel/admin record % not found', v_personnel_id;
  END IF;

  UPDATE public.admin_requests
  SET
    status = 'approved',
    decision_note = COALESCE(p_note, decision_note),
    reviewed_at = NOW(),
    reviewed_by_admin_id = p_decided_by_admin_id
  WHERE id = p_request_id;

  RETURN QUERY
  SELECT ar.id, ar.personnel_id, ar.status, a.role_id
  FROM public.admin_requests ar
  JOIN public.admins a ON a.id = ar.personnel_id
  WHERE ar.id = p_request_id;
END;
$$;


ALTER FUNCTION public.accept_admin_request(p_request_id bigint, p_decided_by_admin_id bigint, p_note text) OWNER TO postgres;

--
-- TOC entry 254 (class 1255 OID 16509)
-- Name: enforce_max_primary_contacts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_max_primary_contacts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.is_primary = TRUE THEN
    IF (SELECT COUNT(*) FROM emergency_contacts
        WHERE owner_user_id = NEW.owner_user_id
          AND is_primary = TRUE
          AND (TG_OP = 'INSERT' OR id <> NEW.id)) >= 3 THEN
      RAISE EXCEPTION 'Max 3 primary contacts allowed';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


