CREATE TABLE public.users (
    id integer NOT NULL,
    firebase_uid character varying(128) NOT NULL,
    full_name character varying(50) NOT NULL,
    email character varying(320) NOT NULL,
    phone_number character varying(20),
    profile_image bytea,
    role character varying(20) DEFAULT 'citizen'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    profile_image_content_type character varying(50),
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    beacon_code character varying(12),
    profile_image_url text,
    status text DEFAULT 'active'::text NOT NULL,
    CONSTRAINT chk_users_role CHECK (((role)::text = ANY ((ARRAY['citizen'::character varying, 'student'::character varying])::text[]))),
    CONSTRAINT chk_users_status CHECK ((status = ANY (ARRAY['active'::text, 'deactivated'::text])))
);


